head.script:
// ====== CẤU HÌNH ======
scwin.API_BASE   = "http://localhost:8081";              // địa chỉ backend Spring Boot
// Tự lấy tiền tố ứng dụng từ địa chỉ đang mở, ví dụ "/text" (hoặc "" nếu chạy ở thư mục gốc)
scwin.CTX        = window.location.pathname.replace(/\/websquare\/websquare\.html.*$/, "");
scwin.WS_ENTRY   = scwin.CTX + "/websquare/websquare.html";   // trang khởi chạy WebSquare
scwin.PAGE_LOGIN = scwin.CTX + "/authPage/LoginPage.xml";     // trang đăng nhập

// Chuyển cả trang sang một màn hình WebSquare khác
scwin.goPage = function (w2xPath) {
	window.location.href = scwin.WS_ENTRY + "?w2xPath=" + w2xPath;
};

scwin.onpageload = function () {
	ibx_fullName.focus();
};

scwin.showMsg = function (text, isSuccess) {
	txt_msg.setValue(text);
	txt_msg.removeClass("is-error");
	txt_msg.removeClass("is-success");
	txt_msg.addClass(isSuccess ? "is-success" : "is-error");
	txt_msg.setStyle("display", "block");
};
scwin.hideMsg = function () {
	txt_msg.setStyle("display", "none");
};

scwin.getErrorText = function (json) {
	if (json && json.data && typeof json.data === "object") {
		for (var field in json.data) {
			if (json.data.hasOwnProperty(field)) { return json.data[field]; }
		}
	}
	return (json && json.message) ? json.message : "Có lỗi xảy ra, vui lòng thử lại.";
};

// Kiểm tra dữ liệu trước khi gửi (cùng quy tắc với backend)
scwin.validate = function (d) {
	if (d.fullName === "") { ibx_fullName.focus(); return "Vui lòng nhập họ và tên."; }
	if (!/^[A-Za-z0-9._-]{4,50}$/.test(d.username)) {
		ibx_username.focus();
		return "Tên đăng nhập 4-50 ký tự, chỉ gồm chữ không dấu, số, dấu chấm, gạch dưới, gạch ngang.";
	}
	if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(d.email)) { ibx_email.focus(); return "Email không đúng định dạng."; }
	if (d.phone !== "" && !/^\+?[0-9 .()-]{8,20}$/.test(d.phone)) { ibx_phone.focus(); return "Số điện thoại không đúng định dạng."; }
	if (!/^(?=.*[A-Za-z])(?=.*\d)(?=.*[^A-Za-z0-9]).{8,72}$/.test(d.password)) {
		sct_password.focus();
		return "Mật khẩu tối thiểu 8 ký tự, gồm chữ, số và ký tự đặc biệt.";
	}
	if (d.password !== d.confirmPassword) { sct_confirm.focus(); return "Mật khẩu nhập lại không khớp."; }
	return "";
};

scwin.btn_register_onclick = function () {
	var d = {
		fullName: (ibx_fullName.getValue() || "").trim(),
		username: (ibx_username.getValue() || "").trim(),
		email: (ibx_email.getValue() || "").trim(),
		phone: (ibx_phone.getValue() || "").trim(),
		password: sct_password.getValue() || "",
		confirmPassword: sct_confirm.getValue() || ""
	};

	var error = scwin.validate(d);
	if (error !== "") { scwin.showMsg(error); return; }

	scwin.hideMsg();
	btn_register.setDisabled(true);

	fetch(scwin.API_BASE + "/api/auth/register", {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: JSON.stringify({
			username: d.username, password: d.password, fullName: d.fullName,
			email: d.email, phone: d.phone
		})
	}).then(function (res) {
		return res.json();
	}).then(function (json) {
		if (!json || !json.success) {
			btn_register.setDisabled(false);
			scwin.showMsg(scwin.getErrorText(json));
			return;
		}
		scwin.showMsg("Đăng ký thành công. Đang chuyển sang trang đăng nhập...", true);
		setTimeout(function () { scwin.goPage(scwin.PAGE_LOGIN); }, 1500);
	}).catch(function () {
		btn_register.setDisabled(false);
		scwin.showMsg("Không kết nối được máy chủ. Vui lòng kiểm tra backend đang chạy.");
	});
};

scwin.form_onkeyup = function (e) {
	if (e && e.keyCode === 13) { scwin.btn_register_onclick(); }
};

scwin.lnk_login_onclick = function () {
	scwin.goPage(scwin.PAGE_LOGIN);
};
